// ============================================================
// ROTEADOR DA CAPACIDADE
// ============================================================
// Escolhe a consulta numa lista FECHADA: o SQL nunca vem do pedido,
// só os valores, conferidos aqui e passados como parâmetro.
// Quem pode o quê vem do cargo da sessão (central.sessao), nunca do corpo.
// Erros saem como "status|mensagem" pela saída de erro.
// ============================================================
const GESTAO = ['COORDENADOR', 'GERENTE', 'DIRETOR'];
const EDICAO = ['GERENTE', 'DIRETOR'];
const TODOS = ['COLABORADOR', 'COORDENADOR', 'GERENTE', 'DIRETOR'];

function pedido() {
  try {
    return { metodo: 'POST', dados: $('Acao').first().json.body || {} };
  } catch (e) {
    return { metodo: 'GET', dados: $('Consulta').first().json.query || {} };
  }
}
const { metodo, dados } = pedido();

const usuario = $input.first().json.usuario;
if (!usuario) throw new Error('401|SESSAO_EXPIRADA|A sua sessão expirou. Saia e entre de novo.');

const falha = (m) => { throw new Error('400|DADO_INVALIDO|' + m); };
function inteiro(v, nome, padrao) {
  if (v === undefined || v === null || v === '') {
    if (padrao !== undefined) return padrao;
    falha('Informe ' + nome + '.');
  }
  const n = Number(v);
  if (!Number.isInteger(n) || n < 1 || n > 1e12) falha(nome + ' inválido.');
  return n;
}
function codigo(v, nome) {
  if (typeof v !== 'string' || !/^[A-Za-z0-9_-]{1,40}$/.test(v)) falha(nome + ' inválido.');
  return v;
}
function data(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v) || isNaN(Date.parse(v))) falha('Data inválida.');
  return v;
}
const cenario = (d) => inteiro(d.cenario, 'o cenário', 1);

const ROTAS = {
  GET: {
    contexto:        [GESTAO, 'select central.api_contexto() as r', () => []],
    heatmap:         [GESTAO, 'select central.api_heatmap($1::bigint, $2::date, $3::int) as r',
                      (d) => [cenario(d), data(d.inicio), inteiro(d.semanas, 'o número de semanas', 10)]],
    timeline:        [GESTAO, 'select central.api_timeline($1::bigint, $2::text) as r',
                      (d) => [cenario(d), codigo(d.projeto, 'Projeto')]],
    alertas:         [GESTAO, 'select central.api_alertas($1::bigint) as r', (d) => [cenario(d)]],
    disponibilidade: [GESTAO, 'select central.api_disponibilidade($1::bigint) as r', (d) => [cenario(d)]],
    itens:           [GESTAO, 'select central.api_itens($1::bigint) as r', (d) => [cenario(d)]],
    previsao:        [GESTAO, 'select central.api_previsao($1::bigint) as r', (d) => [cenario(d)]],
    equipes:         [GESTAO, 'select central.api_equipes() as r', () => []],
    calendario:      [TODOS,  'select central.api_calendario() as r', () => []],
  },
  POST: {
    simular:  [GESTAO, 'select central.api_simular($1::bigint, $2::bigint, $3::text, $4::bigint) as r',
               (d) => [cenario(d), inteiro(d.item, 'o item'), codigo(d.sprint, 'Sprint'), inteiro(d.responsavel, 'o responsável')]],
    mover:    [EDICAO, 'select central.api_mover($1::bigint, $2::bigint, $3::text, $4::bigint) as r',
               (d) => [cenario(d), inteiro(d.item, 'o item'), codigo(d.sprint, 'Sprint'), inteiro(d.responsavel, 'o responsável')]],
    desfazer: [EDICAO, 'select central.api_desfazer($1::bigint, $2::bigint) as r',
               (d) => [cenario(d), inteiro(d.item, 'o item')]],
  },
};

const rota = ROTAS[metodo][String(dados.rota || '')];
if (!rota) throw new Error('404|ROTA_DESCONHECIDA|Rota não encontrada.');
if (!rota[0].includes(usuario.cargo)) {
  throw new Error(metodo === 'POST' && rota[0] === EDICAO
    ? '403|SO_GESTAO_EDITA|Só gerência e diretoria mudam o planejamento.'
    : '403|SEM_ACESSO|Seu cargo não tem acesso a esta informação.');
}

return [{ json: { sql: rota[1], params: rota[2](dados) } }];

// A função do banco devolve o JSON pronto; { erro, codigo } vira 400.
const r = $input.first().json.r;
if (r && typeof r === 'object' && !Array.isArray(r) && typeof r.erro === 'string') {
  return [{ json: { http: 400, body: { erro: r.erro, codigo: r.codigo || 'INVALIDO' } } }];
}
return [{ json: { http: 200, body: r === undefined ? null : r } }];

// "status|CODIGO|mensagem" das guardas vira resposta; outro erro (banco fora do ar) vira 503.
const bruto = $input.first().json.error;
const texto = String((bruto && bruto.message) || bruto || '').replace(/\s*\[line \d+\]\s*$/, '');
const m = texto.match(/^(\d{3})\|([A-Z_]+)\|(.*)$/s);
return [{
  json: m
    ? { http: Number(m[1]), body: { erro: m[3], codigo: m[2] } }
    : { http: 503, body: { erro: 'O serviço de capacidade está indisponível. Tente de novo em instantes.', codigo: 'INDISPONIVEL' } },
}];
